function recordDialogError(original){if(typeof document.createElement!=='function')return;const dialog=['import-dialog','ai-dialog','source-dialog','integration-dialog'].map(id=>$('#'+id)).find(d=>d?.open);if(!dialog)return;let details=dialog.querySelector('.local-error-details');if(!details){details=document.createElement('details');details.className='local-error-details advanced-details';const summary=document.createElement('summary');summary.dataset.en='Error details';summary.dataset.zh='错误详情';details.appendChild(summary);details.appendChild(document.createElement('pre'));(dialog.querySelector('.modal-body')||dialog).appendChild(details);}details.hidden=false;details.querySelector('summary').textContent=language==='en'?'Error details':'错误详情';details.querySelector('pre').textContent=original;}
function errorMessage(error){const original=String(error?.message??error??'');const translated=uiText(original);recordDialogError(original);if($('#technical-error-original'))$('#technical-error-original').textContent=original;if($('#technical-error-details'))$('#technical-error-details').hidden=!original;if(language==='zh'&&translated===original&&/[A-Za-z]/.test(original))return '请求未完成。请核对输入或连接状态；原始错误可在“高级错误详情”查看。';return translated;}
function applyEvidenceUpdate(data){
 const previous=new Map(state.claims.map(c=>[c.id,structuredClone(c)]));
 state.workspaceVersion++;state.draftVersion++;state.fileEpoch++;state.sources=data.sources;state.analysis=data.analysis;state.image=null;state.imageRequest=null;state.aiRequest=null;state.ai=null;
 const next=state.claims.map(c=>({...c,status:c.status==='unsupported'?'unsupported':'needs_review'}));
 for(const c of data.analysis.claims){if(!previous.has(c.id)){next.push(structuredClone(c));state.claimProvenance[c.id]={origin:'deterministic_rules',initial_text:c.text};}}
 state.claims=next;for(const c of previous.values())if(c.status==='reviewed')auditClaim(c.id,'evidence_changed_review_reset');
 state.dirty=true;refs=new Map();refSequence=0;render();setBusyUI();
}
function guidedEvidenceContent(){const text=$('#evidence-text').value;if(!text.trim())throw new Error(language==='en'?'Paste the original evidence text first.':'请先粘贴证据原文。');return JSON.stringify({case_id:state.case.dispute_id,order_id:state.case.order_id,evidence:[{label:$('#evidence-label').value.trim()||(language==='en'?'Pasted evidence':'粘贴材料'),kind:$('#evidence-kind').value||'note',occurred_at:$('#evidence-occurred-at').value.trim(),assertion:$('#evidence-assertion').value||'',synthetic:false,text}]});}
function allSources(){return state.case ? [state.case.source,...state.sources] : [];}
function sourceById(id){return allSources().find(s=>s.source_id===id);}
function sourceRole(s){if(s.image_provenance)return '图片衍生转录 · 已人工核对';if(s.kind==='api_snapshot') return '支付平台记录';if(['buyer_nonreceipt','partial_delivery','buyer_acceptance'].includes(s.assertion))return '买家陈述';if(s.assertion==='seller_delivery_claim'||s.kind==='delivery')return '商户材料';if(s.kind==='contract')return '合同 / 范围';if(s.kind==='access_log')return '访问记录';return '沟通材料';}
function sourceLabel(s){return s.label||s.filename;}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=uiText(msg);$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function newRequestId(){return globalThis.crypto?.randomUUID?.()||`el-${Date.now()}-${Math.random().toString(36).slice(2)}`;}
function isCurrent(op,checkDraft=false){return state.pending===op&&!op.cancelled&&op.workspaceVersion===state.workspaceVersion&&(!checkDraft||op.draftVersion===state.draftVersion);}
function setBusyUI(){
 const busy=!!state.pending;state.busy=busy;
 for(const id of ['open-import','add-evidence','export-json','export-text','review-next-toolbar'])$('#'+id).disabled=busy||state.offline;
 $('#submit-import').disabled=busy||(state.importMode==='paypal'&&!state.status?.paypal?.configured);
 $('#run-ai').disabled=busy||!$('#ai-consent').checked||!state.status?.ai?.configured;
 $('#recover-ai').disabled=busy;
 updateImageControls();
 $('#operation-notice').hidden=!busy;
 if(busy){$('#operation-title').textContent=({ai:'等待模型响应',import:'导入与核对材料',export:'生成审核包',reset:'恢复演示材料',recover:'查询上次请求状态',image:'提取截图文字',imageRecover:'查询截图提取结果',imageAdmit:'核对并加入衍生文本'})[state.pending.kind]||'正在处理';$('#operation-detail').textContent=['ai','import','image','imageRecover'].includes(state.pending.kind)?'停止等待只会阻止结果写入当前工作区，不保证远程调用已取消。':'正在处理当前工作区的固定快照；过期结果不会覆盖新编辑。';}
}
function beginOperation(kind,requestId=newRequestId()){
 if(state.pending)throw new Error('已有操作正在进行。请先等待或停止等待。');
 const op={kind,requestId,workspaceVersion:state.workspaceVersion,draftVersion:state.draftVersion,controller:new AbortController(),cancelled:false};state.pending=op;setBusyUI();return op;
}
function finishOperation(op){if(state.pending===op){state.pending=null;setBusyUI();}}
function cancelPending(reason='已停止等待；当前草稿未被替换。'){
 const op=state.pending;if(!op)return;
 op.cancelled=true;op.controller.abort();
 if((op.kind==='ai'||op.kind==='recover')&&state.aiRequest?.id===op.requestId)state.aiRequest.state='uncertain';
 if(['image','imageRecover'].includes(op.kind)&&state.imageRequest?.id===op.requestId)state.imageRequest.state='uncertain';
 state.pending=null;setBusyUI();toast(reason);
}
function auditClaim(id,action){const last=state.reviewLog.at(-1);if(last?.claim_id===id&&last.action===action&&action==='edited')return;state.reviewLog.push({at:new Date().toISOString(),claim_id:id,action,draft_revision:state.draftVersion,workspace_version:state.workspaceVersion});if(state.reviewLog.length>500)state.reviewLog.shift();}
// Ephemeral bearer capability for isolation only, not authentication or identity.
// No storage: reload intentionally loses request recovery and observations.
let browserSession;
function sessionCapability(){return browserSession??=Array.from(crypto.getRandomValues(new Uint8Array(32)),v=>v.toString(16).padStart(2,'0')).join('');}
async function api(path,body,settings={}){
 const controller=settings.controller||new AbortController();let timedOut=false;
 const timer=setTimeout(()=>{timedOut=true;controller.abort();},settings.timeoutMs||75000);
 const options={headers:{'Accept':'application/json','X-EvidenceLens-Session':sessionCapability()},signal:controller.signal};
 if(settings.requestId)options.headers['X-EvidenceLens-Request-ID']=settings.requestId;
 if(body!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.body=JSON.stringify(body);}
 try{const response=await fetch(path,options);let data;try{data=await response.json();}catch{throw new Error('本地服务返回了无法识别的内容。');}if(!response.ok){const error=new Error(data.error||`请求失败 (${response.status})`);error.httpStatus=response.status;error.response=data;throw error;}return data;}
 catch(error){if(timedOut){const timeout=new Error('等待超时，远程调用结果尚未确认。不要直接重复发起；可查询上次请求结果。');timeout.uncertain=true;throw timeout;}throw error;}
 finally{clearTimeout(timer);}
}
async function refreshStatus(){const status=await api('/api/status');state.status=status;state.offline=status.mode==='offline_preview';renderIntegrationStatus();setBusyUI();return status;}
function integrationText(integration){if(!integration?.configured)return '未配置 · 未验证';if(integration.connection_verified)return `最近一次调用成功 · ${dateLabel(integration.last_success_at)}`;if(integration.latest_attempt?.state==='failed')return '已配置 · 最近调用失败（未通过验证）';return '已配置 · 尚未完成实际调用验证';}
