 if($('#public-test-notice'))$('#public-test-notice').hidden=state.status.mode!=='public_test';
 $('#connection-status').textContent=state.offline?uiText('离线预览 · 无网络调用'):(language==='en'?'Public test · real integrations':'公开测试 · 真实集成');
 $('#integration-details').innerHTML=[['PayPal Sandbox',state.status.paypal,['PAYPAL_CLIENT_ID','PAYPAL_CLIENT_SECRET']],[state.status.ai.provider||'模型 API',state.status.ai,[state.status.ai.credential_env||'OPENAI_API_KEY',state.status.ai.model_env||'OPENAI_MODEL']]].map(([title,config,vars])=>`<section class="integration-card"><h3>${esc(title)}</h3><p class="tag ${config.connection_verified?'':'warm'}">${esc(integrationText(config))}</p><details class="advanced-details"><summary>${language==='en'?'Advanced configuration':'高级配置'}</summary><p class="muted">服务端环境变量：${esc(vars.join(' / '))}</p></details>${config.model?`<p class="muted">模型：${esc(config.model)}</p>`:''}</section>`).join('');
 $('#paypal-config-status').textContent=integrationText(state.status.paypal);
