$('#refresh-integration-status').onclick=()=>refreshStatus().catch(e=>toast(e.message));
$('#import-dialog').addEventListener('close',()=>{state.fileEpoch++;if(['import','image','imageRecover','imageAdmit'].includes(state.pending?.kind))cancelPending('导入窗口已关闭；迟到结果不会替换当前材料。');});
